package com.edufox.schoolerp.transport;

import com.edufox.schoolerp.config.DatabaseWriteGuard;
import io.jsonwebtoken.Claims;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@RestController
@RequestMapping("/api/transport")
@RequiredArgsConstructor
@PreAuthorize("hasRole('FACULTY')")
public class TransportController {
    private final JdbcTemplate jdbc;
    private final DatabaseWriteGuard writeGuard;
    private static String school(Authentication a){return String.valueOf(((Claims)a.getDetails()).get("schoolId"));}
    private static String staff(Authentication a){return String.valueOf(((Claims)a.getDetails()).get("staffUid"));}
    private static String s(Object v){return v==null?"":String.valueOf(v).trim();}
    private static int i(Object v){return v==null||s(v).isBlank()?0:Integer.parseInt(s(v));}
    private static Map<String,Object> row(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n+1<v.length;n+=2)m.put(String.valueOf(v[n]),v[n+1]);return m;}

    @GetMapping("/bootstrap") public Map<String,Object> bootstrap(Authentication a){String sc=school(a);Map<String,Object>o=new LinkedHashMap<>();
        o.put("sessions",jdbc.queryForList("SELECT session AS value,session AS label,status FROM TB_Session WHERE school_id=? ORDER BY id DESC",sc));
        o.put("classes",jdbc.queryForList("SELECT c.sec_id AS id,c.class_id AS classId,cn.class_name+' ('+c.section+')' AS label,cn.class_name AS className,c.section FROM TB_Class c JOIN class_name cn ON cn.id=c.class_id AND cn.school_id=c.school_id WHERE c.school_id=? ORDER BY c.class_id,c.sec_id",sc));
        o.put("routes",jdbc.queryForList("SELECT route_id AS id,route_name AS name,status,charges,Route_order AS routeOrder FROM Route_Detail WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY ISNULL(Route_order,999),route_name",sc));
        o.put("stoppages",jdbc.queryForList("SELECT stoppage_id AS id,stoppage_name AS name,pick_up_time AS pickupTime,drop_time AS dropTime,SlabId AS slabId,status FROM stoppage_detail WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY stoppage_name",sc));
        o.put("transportTypes",jdbc.queryForList("SELECT transport_type_id AS id,name,status FROM transport_type WHERE school_id=? AND ISNULL(status,1)=1 ORDER BY name",sc));
        o.put("months",jdbc.queryForList("SELECT month_id AS id,s_month AS name,month_name AS label FROM tb_month ORDER BY id"));
        o.put("slabs",jdbc.queryForList("SELECT SlabID AS id,SlabName AS name FROM SlabMaster WHERE school_id=? ORDER BY SlabID",sc));o.put("schoolId",sc);return o;}

    @GetMapping("/types") public List<Map<String,Object>> types(Authentication a){return jdbc.queryForList("SELECT id,transport_type_id AS transportTypeId,name,status FROM transport_type WHERE school_id=? ORDER BY name",school(a));}
    @PostMapping("/types") public Map<String,Object> addType(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);jdbc.update("INSERT INTO transport_type(transport_type_id,name,school_id,status) VALUES((SELECT ISNULL(MAX(transport_type_id),0)+1 FROM transport_type WHERE school_id=?),?,?,1)",sc,s(r.get("name")),sc);return row("message","Transport type saved");}
    @PutMapping("/types/{id}") public Map<String,Object> updateType(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE transport_type SET name=? WHERE id=? AND school_id=?",s(r.get("name")),id,school(a));return row("message","Transport type updated");}
    @DeleteMapping("/types/{id}") public Map<String,Object> deleteType(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE transport_type SET status=0 WHERE id=? AND school_id=?",id,school(a));return row("message","Transport type deleted");}

    @GetMapping("/routes") public List<Map<String,Object>> routes(Authentication a){return jdbc.queryForList("SELECT Row_id AS id,route_id AS routeId,route_name AS name,status,charges,Route_order AS routeOrder FROM Route_Detail WHERE school_id=? ORDER BY ISNULL(Route_order,999),route_name",school(a));}
    @PostMapping("/routes") public Map<String,Object> addRoute(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);jdbc.update("INSERT INTO Route_Detail(route_id,route_name,status,school_id,created_by,created_date,charges,Route_order) VALUES((SELECT ISNULL(MAX(route_id),0)+1 FROM Route_Detail WHERE school_id=?),?,1,?,?,GETDATE(),?,?)",sc,s(r.get("name")),sc,staff(a),r.get("charges"),r.get("routeOrder"));return row("message","Route saved");}
    @PutMapping("/routes/{id}") public Map<String,Object> updateRoute(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE Route_Detail SET route_name=?,charges=?,Route_order=?,modified_by=?,modified_date=GETDATE() WHERE Row_id=? AND school_id=?",s(r.get("name")),r.get("charges"),r.get("routeOrder"),staff(a),id,school(a));return row("message","Route updated");}
    @DeleteMapping("/routes/{id}") public Map<String,Object> deleteRoute(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE Route_Detail SET status=0,modified_by=?,modified_date=GETDATE() WHERE Row_id=? AND school_id=?",staff(a),id,school(a));return row("message","Route deleted");}

    @GetMapping("/stoppages") public List<Map<String,Object>> stoppages(@RequestParam(required=false)String session,Authentication a){return jdbc.queryForList("SELECT Row_id AS id,stoppage_id AS stoppageId,stoppage_name AS name,pick_up_time AS pickupTime,drop_time AS dropTime,SlabId AS slabId,status FROM stoppage_detail WHERE school_id=? ORDER BY stoppage_name",school(a));}
    @PostMapping("/stoppages") public Map<String,Object> addStoppage(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);jdbc.update("INSERT INTO stoppage_detail(stoppage_id,stoppage_name,pick_up_time,drop_time,status,school_id,created_by,created_date,SlabId) VALUES((SELECT ISNULL(MAX(stoppage_id),0)+1 FROM stoppage_detail WHERE school_id=?),?,?,?,1,?,?,GETDATE(),?)",sc,s(r.get("name")),s(r.get("pickupTime")),s(r.get("dropTime")),sc,staff(a),r.get("slabId"));return row("message","Stoppage saved");}
    @PutMapping("/stoppages/{id}") public Map<String,Object> updateStoppage(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE stoppage_detail SET stoppage_name=?,pick_up_time=?,drop_time=?,SlabId=?,modified_by=?,modified_date=GETDATE() WHERE Row_id=? AND school_id=?",s(r.get("name")),s(r.get("pickupTime")),s(r.get("dropTime")),r.get("slabId"),staff(a),id,school(a));return row("message","Stoppage updated");}
    @DeleteMapping("/stoppages/{id}") public Map<String,Object> deleteStoppage(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE stoppage_detail SET status=0,modified_by=?,modified_date=GETDATE() WHERE Row_id=? AND school_id=?",staff(a),id,school(a));return row("message","Stoppage deleted");}

    @GetMapping("/mappings") public List<Map<String,Object>> mappings(@RequestParam int routeId,Authentication a){return jdbc.queryForList("SELECT m.id,m.route_id AS routeId,m.stoppage_id AS stoppageId,s.stoppage_name AS stoppageName,m.status FROM route_stoppage_mapping m JOIN stoppage_detail s ON s.stoppage_id=m.stoppage_id AND s.school_id=m.school_id WHERE m.school_id=? AND m.route_id=? ORDER BY s.stoppage_name",school(a),routeId);}
    @PostMapping("/mappings") @Transactional public Map<String,Object> saveMappings(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);int route=i(r.get("routeId"));jdbc.update("UPDATE route_stoppage_mapping SET status=0,modified_by=?,modified_date=GETDATE() WHERE school_id=? AND route_id=?",staff(a),sc,route);Object raw=r.get("stoppageIds");if(raw instanceof Collection<?>c)for(Object x:c){int stop=i(x);jdbc.update("IF EXISTS(SELECT 1 FROM route_stoppage_mapping WHERE school_id=? AND route_id=? AND stoppage_id=?) UPDATE route_stoppage_mapping SET status=1,modified_by=?,modified_date=GETDATE() WHERE school_id=? AND route_id=? AND stoppage_id=? ELSE INSERT INTO route_stoppage_mapping(route_id,stoppage_id,status,school_id,created_by,created_date) VALUES(?,?,1,?,?,GETDATE())",sc,route,stop,staff(a),sc,route,stop,route,stop,sc,staff(a));}return row("message","Route stoppage mapping saved");}

    @GetMapping("/vehicles") public List<Map<String,Object>> vehicles(Authentication a){return jdbc.queryForList("SELECT v.id,v.vehicleno_id AS vehicleId,v.vehicle_no AS vehicleNo,v.vehicle_name AS vehicleName,v.transport_type_id AS transportTypeId,COALESCE(t.name,'') AS transportType,v.status FROM vehicle_master v LEFT JOIN transport_type t ON t.transport_type_id=v.transport_type_id AND t.school_id=v.school_id WHERE v.school_id=? ORDER BY v.id DESC",school(a));}
    @PostMapping("/vehicles") public Map<String,Object> addVehicle(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);String no=s(r.get("vehicleNo"));jdbc.update("INSERT INTO vehicle_master(vehicleno_id,transport_type_id,vehicle_no,school_id,created_date,created_by,status,vehicle_name) VALUES(?,?,?,?,GETDATE(),?,1,?)",no,r.get("transportTypeId"),no,sc,staff(a),s(r.get("vehicleName")));return row("message","Vehicle saved");}
    @PutMapping("/vehicles/{id}") public Map<String,Object> updateVehicle(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE vehicle_master SET vehicleno_id=?,transport_type_id=?,vehicle_no=?,vehicle_name=?,modified_by=?,modified_date=GETDATE() WHERE id=? AND school_id=?",s(r.get("vehicleNo")),r.get("transportTypeId"),s(r.get("vehicleNo")),s(r.get("vehicleName")),staff(a),id,school(a));return row("message","Vehicle updated");}
    @DeleteMapping("/vehicles/{id}") public Map<String,Object> deleteVehicle(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE vehicle_master SET status=0,modified_by=?,modified_date=GETDATE() WHERE id=? AND school_id=?",staff(a),id,school(a));return row("message","Vehicle deleted");}

    @GetMapping("/drivers") public List<Map<String,Object>> drivers(Authentication a){return jdbc.queryForList("SELECT d.row_id AS id,d.detail_id AS detailId,d.route_id AS routeId,d.vehicleno_id AS vehicleId,d.drivername AS driverName,d.helpername AS helperName,d.transport_type_id AS transportTypeId,d.driver_expiry_date AS driverExpiryDate,d.insurance_expiry_date AS insuranceExpiryDate,d.mobileno AS mobileNo,d.Ownername AS ownerName,d.upload_document AS uploadDocument FROM driver_vehicle_detail d WHERE d.school_id=? ORDER BY d.row_id DESC",school(a));}
    @PostMapping("/drivers") public Map<String,Object> addDriver(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a);jdbc.update("INSERT INTO driver_vehicle_detail(detail_id,route_id,vehicleno_id,drivername,helpername,transport_type_id,school_id,created_date,created_by,driver_expiry_date,insurance_expiry_date,upload_document,mobileno,Ownername) VALUES((SELECT ISNULL(MAX(detail_id),0)+1 FROM driver_vehicle_detail WHERE school_id=?),?,?,?,?,?,?,GETDATE(),?,?,?,?,?,?)",sc,r.get("routeId"),s(r.get("vehicleId")),s(r.get("driverName")),s(r.get("helperName")),r.get("transportTypeId"),sc,staff(a),s(r.get("driverExpiryDate")),s(r.get("insuranceExpiryDate")),s(r.get("uploadDocument")),s(r.get("mobileNo")),s(r.get("ownerName")));return row("message","Driver vehicle saved");}
    @PutMapping("/drivers/{id}") public Map<String,Object> updateDriver(@PathVariable int id,@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();jdbc.update("UPDATE driver_vehicle_detail SET route_id=?,vehicleno_id=?,drivername=?,helpername=?,transport_type_id=?,driver_expiry_date=?,insurance_expiry_date=?,mobileno=?,Ownername=?,modified_by=?,modified_date=GETDATE() WHERE row_id=? AND school_id=?",r.get("routeId"),s(r.get("vehicleId")),s(r.get("driverName")),s(r.get("helperName")),r.get("transportTypeId"),s(r.get("driverExpiryDate")),s(r.get("insuranceExpiryDate")),s(r.get("mobileNo")),s(r.get("ownerName")),staff(a),id,school(a));return row("message","Driver vehicle updated");}
    @DeleteMapping("/drivers/{id}") public Map<String,Object> deleteDriver(@PathVariable int id,Authentication a){writeGuard.requireWritable();jdbc.update("DELETE FROM driver_vehicle_detail WHERE row_id=? AND school_id=?",id,school(a));return row("message","Driver vehicle deleted");}

    @GetMapping("/students") public List<Map<String,Object>> students(@RequestParam String session,@RequestParam(defaultValue="0")String classId,@RequestParam(defaultValue="")String studentId,@RequestParam(defaultValue="Registered")String status,Authentication a){String sc=school(a);StringBuilder q=new StringBuilder("SELECT st.stu_id AS id,st.stu_id AS studentId,st.registration_no AS registrationNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,cn.class_name+' ('+cl.section+')' AS className,st.class_id AS classId,st.sec_id AS secId,fa.Route_id AS routeId,COALESCE(rd.route_name,'') AS routeName,fa.Stoppage_id AS stoppageId,COALESCE(sd.stoppage_name,'') AS stoppageName,fa.transport_type_id AS transportTypeId,COALESCE(tt.name,'') AS transportType FROM TB_StudentMaster st JOIN student_other_info so ON so.uid=st.uid AND so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id LEFT JOIN (SELECT x.* FROM fee_Assign_Transport x JOIN (SELECT school_id,session,stu_id,MAX(id) id FROM fee_Assign_Transport GROUP BY school_id,session,stu_id) z ON z.id=x.id) fa ON fa.school_id=st.school_id AND fa.session=st.session AND fa.stu_id=st.stu_id LEFT JOIN Route_Detail rd ON rd.school_id=fa.school_id AND rd.route_id=fa.Route_id LEFT JOIN stoppage_detail sd ON sd.school_id=fa.school_id AND sd.stoppage_id=fa.Stoppage_id LEFT JOIN transport_type tt ON tt.school_id=fa.school_id AND tt.transport_type_id=fa.transport_type_id WHERE st.school_id=? AND st.session=? AND st.status=?");List<Object>p=new ArrayList<>(List.of(sc,session,status));if(!s(classId).isBlank()&&!"0".equals(classId)){q.append(" AND st.sec_id=?");p.add(classId);}if(!s(studentId).isBlank()){q.append(" AND st.stu_id=?");p.add(studentId);}q.append(" ORDER BY so.first_name,so.mid_name,so.last_name");return jdbc.queryForList(q.toString(),p.toArray());}
    @PostMapping("/assignments") @Transactional public Map<String,Object> saveAssignments(@RequestBody Map<String,Object>r,Authentication a){writeGuard.requireWritable();String sc=school(a),stf=staff(a),session=s(r.get("session"));Object rows=r.get("rows");int count=0;if(rows instanceof Collection<?>c)for(Object raw:c)if(raw instanceof Map<?,?>m&&Boolean.parseBoolean(s(m.get("selected")))){int stu=i(m.get("studentId")),route=i(m.get("routeId")),stop=i(m.get("stoppageId")),type=i(m.get("transportTypeId"));jdbc.update("DELETE FROM fee_Assign_Transport_Mapping WHERE school_id=? AND stu_id=? AND Assign_id IN (SELECT Assign_id FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=?)",sc,stu,sc,session,stu);jdbc.update("DELETE FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=?",sc,session,stu);jdbc.update("INSERT INTO fee_Assign_Transport(stu_id,Assign_id,Route_id,Stoppage_id,assign_date,session,created_date,created_by,status,school_id,transport_type_id,vehicleNO) VALUES(?,(SELECT ISNULL(MAX(Assign_id),0)+1 FROM fee_Assign_Transport),?,?,GETDATE(),?,GETDATE(),?,1,?,?,?)",stu,route,stop,session,stf,sc,type,s(m.get("vehicleId")));Integer aid=jdbc.queryForObject("SELECT TOP 1 Assign_id FROM fee_Assign_Transport WHERE school_id=? AND session=? AND stu_id=? ORDER BY id DESC",Integer.class,sc,session,stu);Object months=m.get("months");if(months instanceof Collection<?>mc)for(Object mo:mc)jdbc.update("INSERT INTO fee_Assign_Transport_Mapping(Assign_id,stu_id,month_id,school_id,paid_status,stoppage_id,installment_no,charges) VALUES(?,?,?, ?,0,?,?,?)",aid,stu,i(mo),sc,stop,m.get("installmentNo"),m.get("charges"));count++;}return row("updated",count,"message","Transport assignments saved");}

    private String assigned(){return " FROM TB_StudentMaster st JOIN student_other_info so ON so.uid=st.uid AND so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id JOIN fee_Assign_Transport fa ON fa.school_id=st.school_id AND fa.session=st.session AND fa.stu_id=st.stu_id LEFT JOIN Route_Detail rd ON rd.route_id=fa.route_id AND rd.school_id=fa.school_id LEFT JOIN stoppage_detail sd ON sd.stoppage_id=fa.stoppage_id AND sd.school_id=fa.school_id";}
    @GetMapping("/reports/assign-route") public List<Map<String,Object>> assignRoute(@RequestParam String session,@RequestParam(defaultValue="0")String classId,@RequestParam(defaultValue="0")String routeId,Authentication a){String q="SELECT ROW_NUMBER() OVER(ORDER BY st.class_id,st.sec_id,so.first_name,st.registration_no) AS sno,st.registration_no AS registrationNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,cn.class_name+' '+cl.section AS className,COALESCE(rd.route_name,'') AS routeName,COALESCE(sd.stoppage_name,'') AS stoppageName"+assigned()+" WHERE st.school_id=? AND st.session=? AND st.status='registered'";List<Object>p=new ArrayList<>(List.of(school(a),session));if(!"0".equals(classId)){q+=" AND st.sec_id=?";p.add(classId);}if(!"0".equals(routeId)){q+=" AND fa.route_id=?";p.add(routeId);}return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName,st.registration_no",p.toArray());}
    @GetMapping("/reports/student") public List<Map<String,Object>> studentReport(@RequestParam String session,@RequestParam(defaultValue="")String classIds,@RequestParam(defaultValue="")String routeIds,@RequestParam(defaultValue="")String slabId,Authentication a){String q="SELECT st.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,COALESCE(so.mobile,'') AS mobile,cn.class_name+' ('+cl.section+')' AS className,COALESCE(rd.route_name,'') AS routeName,COALESCE(sd.stoppage_name,'') AS stoppageName,COALESCE(sm.SlabName,'') AS slabName,st.stu_id AS studentId"+assigned()+" LEFT JOIN SlabMaster sm ON sm.SlabID=sd.SlabId AND sm.school_id=sd.school_id WHERE st.school_id=? AND st.session=? AND st.status='registered'";List<Object>p=new ArrayList<>(List.of(school(a),session));if(!s(classIds).isBlank())q+=" AND st.sec_id IN ("+classIds.replaceAll("[^0-9,]","")+")";if(!s(routeIds).isBlank())q+=" AND fa.route_id IN ("+routeIds.replaceAll("[^0-9,]","")+")";if(!s(slabId).isBlank()&&!"0".equals(slabId)){q+=" AND sd.SlabId=?";p.add(slabId);}return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName",p.toArray());}
    @GetMapping("/reports/private-students") public List<Map<String,Object>> privateStudents(@RequestParam String session,@RequestParam(defaultValue="")String classIds,Authentication a){String q="SELECT st.sec_id AS secId,st.class_id AS classId,st.stu_id AS studentId,st.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,COALESCE(so.father_name,'') AS fatherName,COALESCE(so.mobile,'') AS mobile,COALESCE(so.r_address,'') AS address,cn.class_name+' ('+cl.section+')' AS className FROM TB_StudentMaster st JOIN student_other_info so ON so.uid=st.uid AND so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id WHERE st.school_id=? AND st.session=? AND st.status='registered' AND NOT EXISTS(SELECT 1 FROM fee_Assign_Transport_Mapping fm WHERE fm.school_id=st.school_id AND fm.stu_id=st.stu_id AND fm.month_id=MONTH(GETDATE()))";List<Object>p=new ArrayList<>(List.of(school(a),session));if(!s(classIds).isBlank())q+=" AND st.sec_id IN ("+classIds.replaceAll("[^0-9,]","")+")";return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName",p.toArray());}
    @GetMapping("/reports/monthwise") public List<Map<String,Object>> monthwise(@RequestParam String session,@RequestParam(defaultValue="")String classIds,@RequestParam(defaultValue="")String monthId,@RequestParam(defaultValue="")String routeId,@RequestParam(defaultValue="0")String status,Authentication a){String q="SELECT st.stu_id AS studentId,st.registration_no AS admissionNo,UPPER(LTRIM(RTRIM(COALESCE(so.first_name,'')+' '+COALESCE(so.mid_name,'')+' '+COALESCE(so.last_name,'')))) AS studentName,cn.class_name+' '+cl.section AS className,cl.class_id AS classId,cl.sec_id AS secId,COALESCE(rd.route_name,'') AS routeName,fa.month_id AS monthId,COALESCE(sd.stoppage_name,'') AS stoppageName,COALESCE(fa.charges,0) AS dueAmount FROM fee_Assign_Transport_Mapping fa JOIN fee_Assign_Transport ft ON ft.Assign_id=fa.Assign_id AND ft.school_id=fa.school_id AND ft.session=? JOIN TB_StudentMaster st ON st.stu_id=fa.stu_id AND st.school_id=fa.school_id AND st.session=ft.session JOIN student_other_info so ON so.registration_no=st.registration_no AND so.school_id=st.school_id JOIN TB_Class cl ON cl.sec_id=st.sec_id AND cl.school_id=st.school_id JOIN class_name cn ON cn.id=st.class_id AND cn.school_id=st.school_id LEFT JOIN Route_Detail rd ON rd.route_id=ft.route_id AND rd.school_id=ft.school_id LEFT JOIN stoppage_detail sd ON sd.stoppage_id=ft.stoppage_id AND sd.school_id=ft.school_id WHERE fa.school_id=?";List<Object>p=new ArrayList<>(List.of(session,school(a)));if(!s(classIds).isBlank())q+=" AND st.sec_id IN ("+classIds.replaceAll("[^0-9,]","")+")";if(!s(monthId).isBlank()&&!"0".equals(monthId)){q+=" AND fa.month_id=?";p.add(monthId);}if(!s(routeId).isBlank()&&!"0".equals(routeId)){q+=" AND ft.route_id=?";p.add(routeId);}if(!"0".equals(status)&&!s(status).isBlank()){q+=" AND st.status=?";p.add(status);}return jdbc.queryForList(q+" ORDER BY st.class_id,st.sec_id,studentName,fa.month_id",p.toArray());}
}
